<div class="right_col" role="main"><div class="d-flex justify-content-between mb-3"><h2>Admission Test Admit Cards</h2><div class="dropdown"><button class="btn btn-primary dropdown-toggle" data-bs-toggle="dropdown">Generate from seat plan</button><div class="dropdown-menu dropdown-menu-end"><?php foreach($plans as $p): ?><?= form_open('school/admission/admit-cards/generate/'.$p->token) ?><button class="dropdown-item"><?= esc($p->title) ?></button><?= form_close() ?><?php endforeach ?></div></div></div><div class="card shadow-sm"><div class="card-body"><table class="table"><thead><tr><th>Card</th><th>Application</th><th>Candidate</th><th>Test</th><th>Generated</th><th></th></tr></thead><tbody><?php foreach($items as $c): ?><tr><td><?= esc($c->card_no) ?></td><td><?= esc($c->application_no) ?></td><td><?= esc($c->student_name) ?></td><td><?= esc($c->test_title) ?></td><td><?= esc($c->generated_at) ?></td><td><a target="_blank" href="<?= base_url('admission/admit-card/'.$c->token) ?>">View</a> · <a href="<?= base_url('admission/admit-card/'.$c->token.'/pdf') ?>">PDF</a></td></tr><?php endforeach ?><?php if(!$items): ?><tr><td colspan="6" class="text-center text-muted">No admit cards generated.</td></tr><?php endif ?></tbody></table></div></div></div>
